#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

class AK375 {
public:
    string ak375(int n, const string& str) {
        string buffer1, buffer2;
        int maxLength = 0;
        int nestedCount = 0;

        for (int i = 0; i < n; i++) {
            char c = str[i];
            if (c == '(') {
                buffer2 += '_';
                int j = i + 1;
                while (j < n && str[j] != ')') {
                    buffer2 += str[j];
                    j++;
                }
                i = j; // skip to position after ')'
            } else if (c == ')') {
                buffer1 += '_';
            } else {
                buffer1 += c;
            }
        }

        // Split buffer2 by '_'
        vector<string> list2;
        stringstream ss2(buffer2);
        string part;
        while (getline(ss2, part, '_')) {
            if (!part.empty()) {
                list2.push_back(part);
            }
        }
        int count2 = list2.size();

        // Find max length in buffer1 parts
        stringstream ss1(buffer1);
        while (getline(ss1, part, '_')) {
            if ((int)part.length() > maxLength) {
                maxLength = part.length();
            }
        }

        return to_string(maxLength) + " " + to_string(count2);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    AK375 solver;
    int n;
    while (cin >> n) {
        string str;
        cin >> str;
        string result = solver.ak375(n, str);
        cout << result << "\n";
    }
    return 0;
